"""Allowlisted public exports. A heuristic privacy check, not an anonymizer."""
from __future__ import annotations

import argparse
import ast
import html
import json
import os
from pathlib import Path, PurePosixPath
import re
import shutil
import subprocess
import sys
import tempfile
import tomllib
import unicodedata

ROOT = Path(__file__).resolve().parent.parent
MANIFEST = 'public-files.json'
EXCLUDED_DIRS = {'.git', '.venv', '__pycache__', '.pytest_cache', '.ruff_cache'}
EXCLUDED_FILES = {'.DS_Store', 'Thumbs.db'}
# Generated by uv or setuptools in the checkout root; never exported (export is manifest-only).
GENERATED_ROOT_FILES = {'uv.lock'}
GITDIR_POINTER = re.compile(rb'gitdir: [^\r\n]+\r?\n?')
FORBIDDEN_PARTS = {'private', 'applications', 'receipts', 'portal_screenshots', 'candidate_profile.md', '.env', '.nav_token', 'credentials.json',
                   'candidate.md', 'preferences.md', 'approved-text.md', 'evidence', 'packets', 'release-deny.txt'}
FORBIDDEN_SUFFIXES = {'.db', '.sqlite', '.sqlite3', '.pdf', '.docx', '.png', '.jpg', '.jpeg', '.zip', '.pem', '.key', '.log', '.jsonl'}
TEXT_SUFFIXES = {'.md', '.py', '.json', '.toml', '.yml', '.yaml', '.txt'}
SPECIAL_FILES = {'.gitignore', '.gitattributes', 'LICENSE', 'NOTICE'}
PATTERNS = {
    'absolute home path': re.compile(r'(?:/Users/|/home/)[A-Za-z0-9_.-]+|[A-Za-z]:\\Users\\[^\\\s]+'),
    'private key': re.compile(r'-----BEGIN (?:[A-Z0-9]+ )*PRIVATE KEY(?: BLOCK)?-----'),
    'provider token': re.compile(r'\b(?:gh[pousr]_[A-Za-z0-9]{20,}|github_pat_[A-Za-z0-9_]{30,}|sk-(?:proj-|ant-)?[A-Za-z0-9_-]{24,}'
                                 r'|glpat-[A-Za-z0-9_-]{20,}|xox[abposr]-[A-Za-z0-9-]{10,}|xapp-\d-[A-Za-z0-9-]{10,}'
                                 r'|AIza[0-9A-Za-z_-]{35}|[sr]k_live_[A-Za-z0-9]{16,})|hooks\.slack\.com/services/[A-Za-z0-9/_-]{20,}'),
    'cloud access key ID': re.compile(r'\b(?:AKIA|ASIA)[A-Z0-9]{16}\b'),
    'bearer token': re.compile(r'(?i)\bbearer\s+[A-Za-z0-9_\-.~+/]{20,}'),
    'JWT': re.compile(r'\beyJ[A-Za-z0-9_-]{15,}\.[A-Za-z0-9_-]{15,}\.[A-Za-z0-9_-]{15,}\b'),
    'URL credentials': re.compile(r'\b[A-Za-z][A-Za-z0-9+.-]*://[^\s/:@]+:[^\s/@]+@'),
    'private tracker reference': re.compile(r'(?:notion\.so/[^\s)]*[a-f0-9]{32}|collection://[a-f0-9-]{32,})', re.I),
    'Norwegian identity number': re.compile(r'(?<![\w])\d{6}[ -]?\d{5}(?![\w])'),
    'international phone number': re.compile(r'(?<![\w+])\+\d(?:[ .()-]{0,2}\d){7,14}(?![\w])'),
}
EMAIL = re.compile(r'\b[A-Za-z0-9.!#$%&\x27*+/=?^_`{|}~-]+@([A-Za-z0-9.-]+\.[A-Za-z]{2,})\b')
EXAMPLE_DOMAINS = {'example.com', 'example.org', 'example.net', 'example.invalid', 'test.invalid'}


class ReleaseError(ValueError):
    pass


def safe_relative(value: str) -> str:
    if (not isinstance(value, str) or not value or '\\' in value or ':' in value
            or any(ord(char) < 32 for char in value)):
        raise ReleaseError('invalid manifest path')
    p = PurePosixPath(value)
    if p.is_absolute() or '..' in p.parts or str(p) != value:
        raise ReleaseError('manifest paths must be canonical relative paths')
    if any(part.casefold() in FORBIDDEN_PARTS or part.casefold() in EXCLUDED_DIRS for part in p.parts):
        raise ReleaseError('private or generated path in manifest')
    if p.suffix.casefold() in FORBIDDEN_SUFFIXES:
        raise ReleaseError('binary or private artifact in manifest')
    if p.suffix not in TEXT_SUFFIXES and p.name not in SPECIAL_FILES:
        raise ReleaseError('unsupported public file type')
    return value


def read_regular(root: Path, name: str) -> bytes:
    path = root
    for component in PurePosixPath(name).parts:
        path = path / component
        if path.is_symlink():
            raise ReleaseError('symlink in public path')
    if not path.is_file():
        raise ReleaseError('public file missing or not a regular file')
    details = path.stat()
    if details.st_nlink != 1:
        raise ReleaseError('hard-linked public file')
    if details.st_size > 1_000_000:
        raise ReleaseError('public file exceeds size limit')
    data = path.read_bytes()
    if b'\x00' in data:
        raise ReleaseError('binary content in public file')
    try:
        data.decode('utf-8')
    except UnicodeDecodeError as exc:
        raise ReleaseError('non-UTF-8 public file') from exc
    return data


def load_manifest(root: Path, data: bytes | None = None) -> list[str]:
    try:
        obj = json.loads(read_regular(root, MANIFEST) if data is None else data)
    except (json.JSONDecodeError, OSError) as exc:
        raise ReleaseError('cannot read public manifest') from exc
    if not isinstance(obj, dict) or set(obj) != {'files'} or not isinstance(obj['files'], list):
        raise ReleaseError('manifest must contain only a files list')
    files = [safe_relative(item) for item in obj['files']]
    if len(files) != len(set(files)) or MANIFEST not in files:
        raise ReleaseError('manifest must include itself once and contain no duplicates')
    return files


def fold(text: str) -> str:
    """Caseless NFKC text without invisible format characters (BOM, soft hyphen, zero-width) and with collapsed whitespace."""
    visible = ''.join(char for char in unicodedata.normalize('NFKC', text) if unicodedata.category(char) != 'Cf')
    return ' '.join(unicodedata.normalize('NFKC', visible.casefold()).split())


def private_terms(path: Path | None, root: Path) -> list[str]:
    if path is None:
        return []
    resolved = path.expanduser().resolve()
    if resolved == root or root in resolved.parents:
        raise ReleaseError('keep private deny terms outside the public repository')
    terms = [fold(line) for line in resolved.read_text(encoding='utf-8-sig').splitlines() if line.strip()]
    if not terms or any(len(term) < 3 for term in terms):
        raise ReleaseError('deny file needs nonempty terms of at least three characters')
    return terms


def matches(text: str, deny: list[str]) -> set:
    keys: set = {category for category, regex in PATTERNS.items() if regex.search(text)}
    if any(m.group(1).casefold() not in EXAMPLE_DOMAINS for m in EMAIL.finditer(text)):
        keys.add('non-example email address')
    folded = fold(text)
    keys.update(('private deny term', index) for index, term in enumerate(deny) if term in folded)
    return keys


def rules(keys: set) -> list[str]:
    return sorted({key[0] if isinstance(key, tuple) else key for key in keys})


def strings(value) -> list[str]:
    if isinstance(value, str):
        return [value]
    if isinstance(value, dict):
        return [text for pair in value.items() for item in pair for text in strings(item)]
    if isinstance(value, list):
        return [text for item in value for text in strings(item)]
    return []


def decoded_views(name: str, body: str) -> list[str]:
    """Text as a reader or parser sees it: across line breaks, HTML entities and escaped string literals.

    Parsing never executes code. YAML and other formats get only the whole-text views.
    """
    source = body.removeprefix('\N{BYTE ORDER MARK}')
    views = [body, html.unescape(body)]
    suffix = PurePosixPath(name).suffix
    if suffix == '.json':
        views += strings(json.loads(source))
    elif suffix == '.toml':
        views += strings(tomllib.loads(source))
    elif suffix == '.py':
        views += [node.value for node in ast.walk(ast.parse(source))
                  if isinstance(node, ast.Constant) and isinstance(node.value, str)]
    return views


def display_name(name: str, deny: list[str]) -> str:
    sensitive = (any(term in fold(name) for term in deny)
                 or any(pattern.search(name) for pattern in PATTERNS.values())
                 or any(m.group(1).casefold() not in EXAMPLE_DOMAINS for m in EMAIL.finditer(name)))
    return '<filename>' if sensitive else name


def findings_for(name: str, body: str, deny: list[str]) -> list[dict[str, object]]:
    result = []
    public_name = display_name(name, deny)
    seen: set = set()
    for number, line in enumerate(body.splitlines(), 1):
        keys = matches(line, deny)
        seen |= keys
        result.extend({'file': public_name, 'line': number, 'rule': rule} for rule in rules(keys))
    try:
        hidden = set().union(*(matches(view, deny) for view in decoded_views(name, body))) - seen
    except (ValueError, SyntaxError, RecursionError, MemoryError):
        result.append({'file': public_name, 'rule': 'cannot parse file to check escaped strings'})
    else:
        result.extend({'file': public_name, 'rule': rule + ' (escaped or split across lines)'} for rule in rules(hidden))
    if any(term in fold(name) for term in deny):
        result.append({'file': '<filename>', 'rule': 'private deny term in filename'})
    elif public_name == '<filename>':
        result.append({'file': '<filename>', 'rule': 'sensitive filename'})
    return result


def git_findings(root: Path, names: list[str], blobs: dict[str, bytes], deny: list[str]) -> list[dict[str, object]]:
    """Tracked names, file modes and staged blobs of manifest files. Earlier commits are not scanned."""
    git = ['git', '-c', 'core.fsmonitor=false', '-C', str(root)]
    findings: list[dict[str, object]] = []
    entries: list[tuple[str, str, str]] = []
    try:
        listed = subprocess.run([*git, 'ls-files', '-s', '-z'], capture_output=True, check=True).stdout
        for record in filter(None, listed.split(b'\x00')):
            meta, _, path = record.partition(b'\t')
            mode, sha, _stage = meta.decode('ascii').split()
            entries.append((path.decode('utf-8'), mode, sha))
        staged = [(name, sha) for name, _, sha in entries if name in names]
        batch = subprocess.run([*git, 'cat-file', '--batch'], input=''.join(sha + '\n' for _, sha in staged).encode(),
                               capture_output=True, check=True).stdout
        offset = 0
        for name, _ in staged:
            header_end = batch.index(b'\n', offset)
            size = int(batch[offset:header_end].split()[2])
            data = batch[header_end + 1:header_end + 1 + size]
            offset = header_end + 2 + size
            if data == blobs.get(name):
                continue
            try:
                text = None if b'\x00' in data else data.decode('utf-8')
            except UnicodeDecodeError:
                text = None
            if text is None:
                findings.append({'file': display_name(name, deny), 'rule': 'staged content is not UTF-8 text', 'source': 'Git index'})
            else:
                findings.extend({**item, 'source': 'Git index'} for item in findings_for(name, text, deny))
    except (OSError, subprocess.CalledProcessError, UnicodeDecodeError, ValueError, IndexError):
        return [{'rule': 'cannot inspect Git index'}]
    if any(name not in names for name, _, _ in entries):
        findings.append({'rule': 'tracked file outside public manifest'})
    if any(mode not in ('100644', '100755') for _, mode, _ in entries):
        findings.append({'rule': 'tracked symlink, submodule or special file'})
    return findings


def inspect(root: Path = ROOT, deny_file: Path | None = None) -> tuple[list[dict[str, object]], dict[str, bytes]]:
    root = root.resolve()
    manifest_data = read_regular(root, MANIFEST)
    names = load_manifest(root, manifest_data)
    deny = private_terms(deny_file, root)
    findings: list[dict[str, object]] = []
    blobs = {}
    for name in names:
        try:
            data = manifest_data if name == MANIFEST else read_regular(root, name)
            findings.extend(findings_for(name, data.decode('utf-8'), deny))
            blobs[name] = data
        except (ReleaseError, OSError):
            public_name = display_name(name, deny)
            findings.append({'file': public_name, 'rule': 'missing, unsafe or unreadable file'})
    for current, dirs, files in os.walk(root, followlinks=False):
        current_path = Path(current)
        for directory in list(dirs):
            child = current_path / directory
            if child.is_symlink():
                findings.append({'file': '<symlink>', 'rule': 'directory symlink in source tree'})
                dirs.remove(directory)
            elif directory in EXCLUDED_DIRS or (current_path == root and directory.endswith('.egg-info')):
                dirs.remove(directory)
        for filename in files:
            child = current_path / filename
            name = child.relative_to(root).as_posix()
            if child.is_symlink():
                findings.append({'file': '<symlink>', 'rule': 'file symlink in source tree'})
            elif name in names or filename in EXCLUDED_FILES or name in GENERATED_ROOT_FILES:
                continue
            elif name == '.git' and child.stat().st_size < 4096 and GITDIR_POINTER.fullmatch(child.read_bytes()):
                continue  # Linked worktree or submodule metadata; safe_relative keeps .git out of every export.
            else:
                findings.append({'file': '<unlisted>', 'rule': 'file outside public manifest'})
    # Even files inside normally excluded caches must never be tracked publicly.
    if (root / '.git').exists():
        findings.extend(git_findings(root, names, blobs, deny))
    return findings, blobs


def export(root: Path, output: Path, deny_file: Path | None = None) -> int:
    root = root.resolve()
    # No overwrite, no source-tree exports and no .git/history inheritance.
    output = output.expanduser().absolute()
    if output.exists() or output.is_symlink():
        raise ReleaseError('export target must not exist')
    resolved = output.resolve()
    inside_source = any(part.exists() and part.samefile(root) for part in (resolved, *resolved.parents))
    if resolved == root or root in resolved.parents or inside_source:
        raise ReleaseError('export target must be outside the source tree')
    findings, blobs = inspect(root, deny_file)
    if findings:
        raise ReleaseError('privacy check failed; run check to see rule locations')
    output.parent.mkdir(parents=True, exist_ok=True)
    temporary = Path(tempfile.mkdtemp(prefix='.jobkit-export-', dir=output.parent))
    try:
        for name, data in blobs.items():
            target = temporary / name
            target.parent.mkdir(parents=True, exist_ok=True)
            target.write_bytes(data)
        if output.exists() or output.is_symlink():
            raise ReleaseError('export target appeared during export')
        temporary.rename(output)
    finally:
        if temporary.exists():
            shutil.rmtree(temporary)
    return len(blobs)


def main(argv: list[str] | None = None) -> int:
    parser = argparse.ArgumentParser(description=__doc__)
    sub = parser.add_subparsers(dest='command', required=True)
    check = sub.add_parser('check', help='check allowlisted files, unexpected files and staged Git content; does not scan Git history')
    check.add_argument('--deny-file', type=Path)
    out = sub.add_parser('export', help='export checked bytes to a new directory without Git history')
    out.add_argument('--output', type=Path, required=True)
    out.add_argument('--deny-file', type=Path)
    args = parser.parse_args(argv)
    try:
        if args.command == 'check':
            findings, blobs = inspect(ROOT, args.deny_file)
            print(json.dumps({'ok': not findings, 'files_checked': len(blobs), 'findings': findings,
                              'git_index_checked': (ROOT / '.git').exists(), 'history_scanned': False}, indent=2))
            return 1 if findings else 0
        count = export(ROOT, args.output, args.deny_file)
        print(json.dumps({'ok': True, 'files_exported': count, 'history_included': False}))
        return 0
    except (ReleaseError, OSError, UnicodeError, ValueError) as exc:
        # Never echo private source text, deny terms or OS error paths.
        message = str(exc) if isinstance(exc, ReleaseError) else 'unreadable or invalid input'
        print(json.dumps({'ok': False, 'error': message}), file=sys.stderr)
        return 1


if __name__ == '__main__':
    raise SystemExit(main())
